
// Bible verses separated from the Bible selector UI.
// Add the remaining books, chapters, verses, and versions here.

final Map<String, Map<String, Map<int, Map<int, String>>>>
    bibleVersions = {
    'OG': {
    'Genesis': {
      1: {
        1: 'O KĨAMBĨRĨRIA-RĨ, Ngai aatũmire kũgĩe matu-inĩ na gũkũ thĩ. ',

        2: 'Nayo thĩ ndĩarĩ ũrĩa yatariĩ; yarĩ o ũguo ũtheri; o nakuo kũu guothe kũriku gũtarĩ gĩturi kwahumbĩtwo no nduma.Na roho wa Ngai aatũire acuhĩrĩire kũu maĩ maarĩ.',

        3: 'Nake Ngai akiuga atĩrĩ, Nĩkũgĩe ũtheri; gũgĩkĩgĩa ũtheri.',

        4: 'Naguo ũtheri ũcio Ngai akĩwona atĩ nĩ mwega; ningĩ Ngai akĩamũrania ũtheri na nduma.',

        5: 'Naguo ũtheri ũcio Ngai akĩũtua Mũthenya,nayo nduma akĩmĩtua Ũtukũ. Nakuo gũkĩgĩa hwaĩ-inĩ, na gũkĩgĩa rũcinĩ; ũcio ũgĩtuĩka mũthenya ũmwe.',

        6: 'Ningĩ Ngai akiuga atĩrĩ, Nĩkũgĩe mũtambũrũko wa matu-mairũ gatagatĩ-inĩ ka maĩ, naguo wamũranie maĩ maya na maya mangĩ.',
           
        7: 'Nake Ngai agĩĩkĩra mũtambũrũko ũcio, agĩkĩamũrania maĩ marĩa maarĩ thĩ ya mũtambũrũko ũcio na marĩa maarĩ igũrũ rĩaguo; gũgĩtuĩka o ũguo.',   
        
        8: 'Ngai agĩgĩtua mũtambũrũko ũcio wa matu-mairũ Igũrũ. Nakuo gũkĩgĩa hwaĩ-inĩ, na gũkĩgĩa rũcinĩ; ũcio ũgĩtuĩka mũthenya ũngĩ, wa kerĩ.',

        9: 'Ningĩ Ngai akiuga atĩrĩ, Maĩ marĩa me kũu thĩ ya igũrũ rĩu nĩmonganĩrio kũndũ kũmwe, kuoneke kũndũ kũniaru; gũgĩtuĩka o ũguo.',

        10: 'Ngai agĩgĩtua kũndũ kũu kũniaru Thĩ, namo maĩ macio monganĩte hamwe akĩmatua Maria; Ngai agĩkĩona atĩ ũguo nĩ wega.',

        11: 'Ningĩ Ngai akiuga atĩrĩ, Thĩ nĩĩmere nyeki, na tũhuti tuothe tũrĩa tũmeraga tũkoimia mbeũ, na mĩtĩ ĩrĩa ĩciaraga maciaro, o mũtĩ ũgaciara ma kĩruka kĩaguo, namo maciaro macio me na mbeũ ciaguo thĩinĩ wamo, mĩthemba ĩo yothe ĩgĩe thĩ; gũgĩtuĩka o ũguo.',

        12: 'Nayo thĩ ĩkĩmera nyeki, na tũhuti tũu tũmeraga tũkoimia mbeũ, o kahuti gakoimia cia kĩruka gĩako, na mĩtĩ ĩrĩa ĩciaraga maciaro, o mũtĩ ũgaciara ma kĩruka kĩaguo, namo maciaro macio me na mbeũ ciaguo thĩinĩ wamo. Ngai agĩkĩona atĩ ũguo nĩ wega.',

        13: 'Nakuo gũkĩgĩa hwaĩ-inĩ, na gũkĩgĩa rũcinĩ; ũcio ũgĩtuĩka mũthenya ũngĩ, wa gatatũ.',

        14:'Ningĩ Ngai akiuga atĩrĩ, Nĩkũgĩe imũrĩ mũtambũrũko-inĩ ũcio wa matu-mairũ ma igũrũ cia kwamũrania mũthenya na ũtukũ; nacio ituĩke imenyithia cia maũndũ, na cia mahinda, na cia matukũ na mĩaka;',

        15:'ningĩ ituĩke imũrĩ mũtambũrũko-inĩ ũcio wa matu-mairũ ma igũrũ cia gũtũmaga thĩ ĩgĩe na ũtheri; gũgĩtuĩka o ũguo.',

        16:'Ngai agĩkĩũmba imũrĩ iria igĩrĩ nene, kĩmũrĩ kĩrĩa kĩnene gũkĩra kĩu kĩngĩ gĩathage mũthenya, nakĩo kĩmũrĩ kĩu kĩnyinyanyinyi gĩathage ũtukũ; na akĩũmba njata o nacio.',

        17: 'We Ngai agĩkĩiga imũrĩ icio mũtambũrũko inĩ ũcio wa matu-mairũ ma igũrũ itũmage thĩ ĩgĩe ũtheri,',

        18:'na ciathage mũthenya na ũtukũ, na ciamũranagie ũtheri na nduma; nake Ngai akĩona atĩ ũguo nĩ wega.',

        19: 'Nakuo gũkĩgĩa hwaĩ-inĩ, na gũkĩgĩa rũcinĩ; ũcio ũgĩtuĩka mũthenya ũngĩ, wa kana.',

        20: 'Ningĩ Ngai akiuga atĩrĩ, Maĩ-rĩ, nĩmahunje o kũhunja ciũmbe ii muoyo iria thiangi rũitũ, ningĩ nyamũ ii njoya nĩciũmbũkage igũrũ rĩa thĩ itheri-inĩ rĩa mũtambũrũko wa matu-mairũ ma igũrũ.',

        21:'Ningĩ Ngai agĩtũma kũgĩe nyamũ iria nene mũno cia iria rĩrĩa inene, na kĩũmbe o gĩothe kĩrĩ muoyo kĩrĩa kĩongoyaga, maĩ magĩkĩhunjwo nĩcio mũno, o nyamũ kĩruka kĩayo, o na akĩũmba nyamũ ciothe cia mathagu iria ii njoya, o nyamũ kĩruka kĩayo; nake Ngai akĩona atĩ ũguo nĩ wega.',

        22: 'We Ngai agĩgĩcirathima, akiuga atĩrĩ, Ciarai mũno, mũthegee, mũiyũre maĩ-inĩ marĩa marĩ maria-inĩ, nacio nyamũ iria ii njoya nĩithegee thĩ.',

        23: 'Nakuo gũkĩgĩa hwaĩ-inĩ, na gũkĩgĩa rũcinĩ; ũcio ũgĩtuĩka mũthenya ũngĩ, wa gatano.', 

        24: 'Ningĩ Ngai akiuga atĩrĩ, Thĩ nĩĩrute ciũmbe irĩ muoyo, o kĩũmbe kĩruka gĩakĩo, nacio nĩ mahiũ, na tũnyamũ tũrĩa tũtambaga, na nyamũ cia werũ, o nyamũ kĩruka kĩayo; gũgĩtuĩka o ũguo.',

        25: 'We Ngai agĩkĩũmba nyamũ cia werũ, o nyamũ kĩruka kĩayo, o namo mahiũ iruka ciamo, o nako kanyamũ o gothe karĩa gatambaga thĩ, o kanyamũ kĩruka gĩako; nake Ngai akĩona atĩ ũguo nĩ wega.',

        26: 'Ningĩ Ngai akiuga atĩrĩ, Nĩtũũmbeni andũ matariĩ ta mũhianĩre witũ, mahaanane na ithuĩ; nao maathage ciũngũyũ cia iria-inĩ, na nyamũ iria irĩ na njoya cia rĩera-inĩ, na nyamũ cia magũrũ mana, na nyamũ ciothe cia gũkũ thĩ, o gwata kanyamũ o gothe gatambi karĩa gatambaga thĩ.',

        27: 'We Ngai agĩgĩtũma kũgĩe andũ, matariĩ ta mũhianĩre wake we mwene, agĩgĩtũma magĩe na mũhianĩre o ta wa Ngai; agĩtũma magĩe kuo marĩ mũndũ mũrũme na mũndũ mũka.',

        28: 'Nake Ngai agĩkĩmarathima, akĩmera atĩrĩ, Ciarai mũno, mũthegee, mũiyũre thĩ, na mũmĩtorie; ningĩ mwathage ciũngũyũ cia iria, na nyamũ iria irĩ njoya cia rĩera-inĩ, o na nyamũ o yothe ĩrĩa ĩthiangaga thĩ.',

        29: 'Ningĩ Ngai akiuga atĩrĩ, Ta onei, nĩndĩmũheete kahuti o gothe karĩa kagĩaga handũ o na ha thĩ yothe, o harĩa yakinya, o karĩa koimagia mbeũ, o na ningĩ mũtĩ o wothe ũrĩa wĩ na maciaro marĩa me mbeũ thĩinĩ wamo; mĩthemba ĩo yothe-rĩ, ĩgũtuĩka ya irio cianyu;',

        30: 'nayo nyamũ o yothe ya werũ, o na nyamũ o yothe ĩrĩ njoya ya rĩera-inĩ, na kanyamũ o gothe karĩa gatambaga thĩ, o icio ciothe ii muoyo-rĩ, nĩndĩciheete kahuti o gothe karĩa karuraga, gatuĩke irio ciacio; gũgĩtuĩka o ũguo.',

        31: 'Ngai agĩkĩona atĩ kĩndũ o gĩothe kĩrĩa ombĩte nĩ kĩega mũno. Nakuo gũkĩgĩa hwaĩ-inĩ, na gũkĩgĩa rũcinĩ; ũcio ũgĩtuĩka mũthenya ũngĩ, wa gatandatũ.',

      },

      2:{
        1:'Igũrũ na thĩ gũgĩkĩrĩka o kũrĩka, o na mwaranĩrie wa ũingĩ wothe wakuo;',

        2:'naguo mũthenya wa mũgwanja Ngai agĩkorũo arĩkĩtie wĩra ũcio wake aarutaga wa ũũmbi; ningĩ mũthenya o ũcio wa mũgwanja akĩhurũka atiganĩte na wĩra wake wothe ũcio aarutĩte wa ũũmbi.',

        3:'Na rĩrĩ, mũthenya ũcio wa mũgwanja-rĩ, Ngai akĩũrathima, akĩwamũra, nĩ ũndũ mũthenya ũcio nĩguo aahurũkire agĩtiga wĩra wake wothe ũrĩa we Ngai aarutĩte wa gũtũma indo igĩe, o na wa gũciũmba.',

        4:'Kĩu nĩkĩo kĩhumo kĩa igũrũ na gĩa thĩ, rĩrĩa ciatũmirũo igĩe kuo, o mũthenya ũrĩa Jehova Ngai ombire thĩ na igũrũ.',

        5:'Na hĩndĩ ĩo thĩ ndĩakoretwo ĩgĩĩte kamũtĩ o na kamwe ga gĩthaka, kana gũkamera kahuti ga gĩthaka o na karĩkũ, amu hĩndĩ ĩo Jehova Ngai ndoirĩirie thĩ mbura, o na gũtiarĩ mũndũ wa kũrĩma mũgũnda;',

        6:'no rĩrĩ, nĩ kĩbii kĩaambataga kiumĩte na thĩ, gĩkaihũgia thĩ igũrũ, o harĩa yakinya.',

        7:'Nake Jehova Ngai akĩũmba mũndũ na rũkũngũ rũa thĩ, agĩcoka akĩmũheeherera mĩhũmũ ya muoyo na marima ma iniũrũ; nake mũndũ ũcio agĩtuĩka mũndũ wĩ muoyo.',

        8:'Naguo mwena ũrĩa riũa rĩrathagĩra, Jehova Ngai agĩthondeka mũgũnda mũirigĩre, o kũrĩa gwetagwo Edeni, na akĩũhanda; na nĩho aaigire mũndũ ũcio ombĩte.',

        9:'Naguo tĩri Jehova Ngai agĩtũma ũmere mũtĩ o wothe wa kwendeka ũkĩonwo, na ũrĩa mwega wa kuuma irio, naguo mũtĩ wa muoyo ũkagĩa o mũgũnda ũcio gatagatĩ, o na mũtĩ wa kũmenyithania wega o na ũũru.',

        10:'Na kwarĩ rũũĩ rũoimĩte kũu Edeni rũa kuunithagĩria mũgũnda ũcio maĩ; naruo rũoima hau, rũkagayũkangana, rũgatuĩka rũa mĩmero ĩna.',

        11:'Rĩĩtwa rĩa ũrĩa wa mbere nĩ Pishoni, na ũcio nĩguo ũrigicĩirie bũrũri wothe wa Havila, kũrĩa gwĩ thahabu;',

        12:'nayo thahabu ya bũrũri ũcio nĩ njega, ningĩ kũu no kũrĩ kĩndũ kĩrĩa gĩĩtagwo bendora na mũthemba wa ihiga ũrĩa wĩtagwo onigithi.',

        13:'Na rĩĩtwa rĩa rũũĩ rũa kerĩ nĩ Gihoni, na rũu nĩruo rũrigicĩirie bũrũri wothe wa Kushi.',

        14:'Na rĩĩtwa rĩa rũũĩ rũa gatatũ nĩ Hidekeli, na rũu nĩruo rũgereire mbarĩ ĩrĩa ĩngĩ ya bũrũri wa Ashuri. Na rũũĩ rũa kana-rĩ, nĩ Farati.',

        15:'Nake Jehova Ngai agĩtwara mũndũ ũcio ombĩte akĩmũiga mũgũnda ũcio warĩ kũu Edeni, aũrutage wĩra, na aũikaragie.',

        16:'Nake Jehova Ngai agĩatha mũndũ ũcio, akĩmwĩra atĩrĩ, Mũtĩ o wothe ũrĩa wĩ mũgũnda ũyũ-rĩ, nĩũrekereirio ũũrĩage;',

        17:'no rĩrĩ, mũtĩ ũrĩa wa kũmenyithania wega o na ũũru, ndũkanaũrĩe, nĩ gũkorũo mũthenya ũrĩa ũkaũrĩa, no mũhaka ũgakua.',

        18:'Ningĩ Jehova Ngai akiuga atĩrĩ, Ti wega mũndũ ũyũ aikare wiki; nĩngũmũũmbĩra mũmũteithia o ũrĩa maaganĩrĩirũo nake.',

        19:'Na rĩrĩ, Jehova Ngai ombire nyamũ o yothe ya gĩthaka na tĩri, o na nyamũ o yothe ĩrĩa ĩrĩ njoya ya rĩera-inĩ, agĩcoka agĩcitwara ciothe kwĩ mũndũ ũcio, nĩguo emenyere ũrĩa egũciĩta; na rĩrĩ, kĩũmbe o gĩothe gĩa icio irĩ muoyo-rĩ, o rĩĩtwa rĩrĩa mũndũ ũcio aagĩtuire, rĩu rĩgĩtuĩka rĩĩtwa rĩakĩo.',

        20:'Nake mũndũ ũcio agĩtua mahiũ mothe marĩĩtwa, o na nyamũ iria ii njoya cia rĩera-inĩ o na nyamũ ciothe cia gĩthaka; no rĩrĩ, ha ũhoro wa mũndũ-rĩ, gũtiakorirũo kwĩ na mũmũteithia maaganĩrĩirũo nake.',

        21:'Nake Jehova Ngai agĩtũma mũndũ ũcio agwatwo nĩ toro mũnene mũno, agĩgĩkoma; ningĩ akĩmũruta rũbaru rũmwe, agĩcoka agĩcokania nyama hau ruuma,',

        22:'naruo rũbaru rũu Jehova Ngai aarutire mũndũ ũcio, akĩrũkũmbania rũgĩtuĩka mũndũ mũka, agĩcoka akĩmũtwara kwĩ mũndũ ũcio.',

        23:'Nake mũndũ ũcio akiuga atĩrĩ, Rĩu kaĩ ũyũ nĩwe ihĩndĩ rĩmwe riumĩte mahĩndĩ-inĩ makwa, o na nyama yumĩte nyama-inĩ ya mwĩrĩ wakwa-ĩ! Nĩ wega etagwo Mũndũ-mũka, tondũ arutirũo thĩinĩ wa Mũndũ-mũrũme.',

        24:'Tondũ wa ũguo-rĩ, mũndũ mũrũme nĩatigane na ithe na nyina, magwatane na mũka, nao erĩ matuĩke mwĩrĩ ũmwe.',

        25:'Nao acio erĩ, mũndũ na mũka, maarĩ njaga, na matiaiguaga thoni.',

      },

      3:{
    1:'Na rĩrĩ, nyamũ-ya-thĩ yaĩrĩ ĩthinga gũkĩra nyamũ o na ĩrĩkĩ thĩinĩ wa nyamũ iria ingĩ cia gĩthaka iria Jehova Ngai ombite. Nayo ĩkĩũria mũndũ mũka ũcio atĩrĩ, Anga Ngai nĩoigĩte atĩ mũtikanarĩe mũtĩ o na ũmwe wa mũgũnda ũyũ?',
    2:'Nake mũndũ mũka agĩcokeria nyamũ-ya-thĩ, akĩmĩra atĩrĩ, Maciaro ma mĩtĩ ya mũgũnda ũyũ, tũrĩe kĩrĩre kũmarĩa;',
    3:'no rĩrĩ, ha ũhoro wa maciaro ma mũtĩ ũrĩa wĩ mũgũnda gatagatĩ-ĩ, Ngai oigĩte atĩrĩ, Mũtikanamarĩe, o na kana mũmũhutie, nĩ getha mũtigakue.',
    4:'Nayo nyamũ-ya-thĩ ĩkĩra mũndũ mũka atĩrĩ, Aca, ti atĩ no mũhaka mũgakua',
    5:'nĩ gũkorũo Ngai nĩoĩ atĩ mũthenya ũrĩa mũkarĩa, hĩndĩ ĩo maitho manyu nĩmakahingũka, mũtuĩke o ta Ngai, mũmenye wega o na ũũru.',
    6:'Nake mũndũ mũka ũcio rĩrĩa onire atĩ mũtĩ ũcio nĩ mwega wa kũuma irio, o na atĩ nĩ wa kwendeka ũkĩonwo na maitho, o na nĩngĩ atĩ nĩ wa kwĩrĩrĩo nĩ ũndũ wa kũkĩrĩgia mũndũ, agĩtua maciaro maguo, akĩmarĩa; o na nĩngĩ akĩhe mũthuriwe nake, o nake akĩrĩa.',
    7:'Namo maitho mao o erĩ makĩhingũka, makĩmenya atĩ me njaga; magĩtũma mathangũ ma mũkũyũ, magĩthondekera tũkuo twa njohero.',
    8:'Nao makĩgua mũgambo wa Jehova Ngai agĩceeranga kũũ mũgũnda rĩta rĩarura, nake mũndũ ũcio na mũka makĩhitha Jehova Ngai kũũ mĩtĩ-inĩ ya mũgũnda, ndakamone.',
    9:'Nake Jehova Ngai agĩĩta mũndũ ũcio, akĩmũũria atĩrĩ, Wĩ ha?',
    10:'Nake akĩuga atĩrĩ, Nĩ kũigua ndaigua mũgambo waku gũkũ mũgũnda, ndetigĩra, nĩ ũndũ nyuma njaga; ndakĩhitha.',
    11:'Nake akĩmũũria atĩrĩ, Nũ ũkwĩrire atĩ wĩ njaga? Kaĩ ũrĩte mũtĩ ũrĩa ndagwathire ngĩkwĩra ndũkanarĩe?',
    12:'Nake mũndũ ũcio akiuga atĩrĩ, Mũndũ mũka ũrĩa waheire tũtũranie nake, nĩwe ũheire maciaro ma mũtĩ ũcio, na nĩ ndarĩa.',
    13:'Nake Jehova Ngai agĩcoka akĩũria mũndũ mũka ũcio atĩrĩ, Ũguo wĩkĩte nĩ atĩa? Nake mũndũ mũka akiuga atĩrĩ, Nyamũ-ya-thĩ nĩyo ĩhenereirie, ndarĩa.',
    14:'Nake Jehova Ngai akĩĩra nyamũ-ya-thĩ atĩrĩ, Tondũ wa ũndũ ũcio wĩkĩte-ĩ, thĩinĩ wa mahiũ mothe, o na thĩinĩ wa nyamũ ciothe cia gĩthaka, wee nĩwatũrũa wĩ mũthahu; gũthĩĩ thĩaga na nda, na kũrĩa ũrĩĩraga rũkũngũ matukũ mothe ma muoyo waku;',
    15:'na nĩngĩ nĩngũtũma inyuĩ na mũndũ mũka ũyũ mũgie thũthũ, o na mbeũ yaku na yake igie thũthũ; mbeũ yake nĩĩgakũgũtha mũtwe, nawe nĩũkamĩgũtha ndiria ya kũgũrũ.',
    16:'Nĩngĩ agĩcoka akĩĩra mũndũ mũka atĩrĩ, Nĩngũkĩhingĩhĩria mũno thĩna waku na mĩtangĩko ĩkonĩĩ ũhoro waku wa kũgia ihu; ũrĩciaraga bwana na ruo, na nĩngĩ merĩrĩria maku nĩmarĩkũgucagĩrĩra kwĩ mũthuri guo, nake nĩarĩgwathaga.',
    17:'Nĩngĩ akĩĩra Adamu o nake atĩrĩ, Tondũ wee nawe nĩwĩtĩkĩire kũigua mũgambo wa mũka guo, warĩa mũtĩ ũcio ndagwathire ngĩkwĩra ũtĩ: Ndũkanarĩe; tondũ wa ũhoro ũcio-rĩ, tĩri nĩwatũrũa wĩ mũthahu nĩ ũndũ waku; ũrĩĩraga irio ciaguo o na thĩna matukũ mothe ma muoyo waku;',
    18:'naguo nĩũgũkũmerera mĩigua, na mahiũ ma nyeki-inĩ, na ũrĩĩraga tũhuti twa mũgũnda;',
    19:'irio ciaku-rĩ, ũrĩĩrĩraga na thithino ya ũthiũ waku, o nginya rĩrĩa ũgacoka thĩ-inĩ nĩ gũkorũo nĩkuo warutĩrĩo; amu wee ũrĩ o rũkũngũ, nĩngĩ ũgacoka ũtũĩke o rũkũngũ.',
    20:'Nake mũndũ ũcio aatuurire mũka Hawa, nĩ ũndũ nĩwe watũĩkire nyina wa arĩa othe magĩaga muoyo.',
    21:'Nĩngĩ Jehova Ngai agĩthondekera Adamu o na mũka nguo cia njũa, akĩmahumba.',
    22:'Nake Jehova Ngai akiuga ũũ: Atĩrĩrĩ, mũndũ ũyũ nĩatũĩkĩte o ta ithuĩ, wa kũmenya wega o na ũũru; na rũu getha ndagatwarĩrĩre guoko, atue maciaro ma mũtĩ wa muoyo o namo, amarĩe, acoke atũũre tene na tene,',
    23:'tondũ ũcio-rĩ, Jehova Ngai akĩmũingata mũgũnda ũcio warĩ kũu Edeni, akarĩmage thĩ-inĩ kũrĩa aarutĩrĩo.',
    24:'Agĩkĩrutũrũra mũndũ ũcio, nĩngĩ agĩcoka akĩga Akerubi mũgũnda ũcio wa Edeni mwena ũrĩa rĩũa rĩrathagĩra, o na rũhiũ rũa rũrĩmĩrĩ rũa mwaki rũehereragĩria na mbarĩ ciothe, nĩguo njĩra ya gũthĩĩ mũtĩ-inĩ wa muoyo ĩkaragio ndĩkagerũo.',
},

      4:{
    1:'Nake mũndũ ũcio akionana na mũka ũcio wake Hawa, nake akĩgia ihu, agĩciara Kaini, akiuga atĩrĩ, Ndĩ kũgia na mwana wa mũndũ mũrũme nĩ ũndũ wa gũteithio nĩ Jehova.',
    2:'Na nĩngĩ agĩciara Habili, mũrũ wa nyina. Nake Habili ũcio aarĩ mũrĩithi wa mbũri; no rĩrĩ, Kaini aarĩ mũrĩmi.',
    3:'Namo matukũ maathiathia, Kaini agĩtwara irio imwe cia mũgũnda, itũĩke ihaki rĩa Jehova.',
    4:'O nake Habili agĩtwara mbũri imwe ciake iria ciarigathatĩrĩwo nĩ mbũri cia rũrũ rĩake, o na maguta mamwe ma cio. Nake Jehova agĩtĩkĩra Habili na ihaki rĩake;',
    5:'no rĩrĩ, ndaigana gwĩtĩkĩra Kaini na ihaki rĩake. Nake Kaini agĩcũnwo nĩ marakara, agĩtuka gĩthiithi.',
    6:'Nake Jehova akĩũria Kaini atĩrĩ, Warakara nĩkĩ? Na nĩngĩ watuka gĩthiithi nĩkĩ?',
    7:'Gĩthĩ ũngĩtũka wega, ndũngĩtĩkĩrĩo o nawe? No nĩngĩ kũngĩtũka atĩ ndũngĩwĩka wega-rĩ, wĩhia ũgũkuoheria mũromo-inĩ; nakuo kwĩrĩrĩria kwaguo nĩgũkũrorete, no rĩrĩ, wee no nginya kwaguo ũũhootage.',
    8:'Nake Kaini akĩĩra Habili mũrũ wa nyina ũhoro ũcio. Na rĩrĩ, gũgĩkinya atĩrĩ, atĩ hĩndĩ maarĩ mũgũnda Kaini agĩkĩrĩra Habili mũrũ wa nyina, akĩmũũraga.',
    9:'Nake Jehova akũũria Kaini atĩrĩ, Mũrũ wa nyũkwa Habili-rĩ, e ha? Nake Kaini akĩmũcokeria akiuga atĩrĩ, Ndĩ nĩĩ? Kaĩ akĩrĩ nĩĩ mũmenyereri wa mũrũ wa maitũ?',
    10:'Nake akĩmũũria atĩrĩ, Nĩ atĩa wĩkĩte? Mũgambo wa thakame ya mũrũ wa nyũkwa nĩũrangaira uumĩte thĩ.',
    11:'Na rĩu, wee nĩwagwatwo nĩ kĩrumi kiumanĩte na thĩ, ũcio wathamirie kanua wanĩrĩrie thakame ya mũrũ wa nyũkwa guoko-inĩ gwaku;',
    12:'warĩma mũgũnda, tĩrĩ ndwagacoka gũkuonera kĩa kiunaga hinya-inĩ waguo; nĩngĩ ũgũtũĩka mũũri wa kũũrũraga gũkũ thĩ.',
    13:'Nake Kaini akĩĩra Jehova atĩrĩ, Iherithia rĩakwa rĩkũnena gũkĩra rĩrĩa ingihota gwĩtiiria.',
    14:'Atĩrĩrĩ, ũmũthĩ nĩwanyangita wangirania na thĩ o harĩa wakinya, na nĩngũtũũra ndiganĩrĩirwo na ũthiũ waku, ndũũre ndĩ mũũri wa kũũrũraga gũkũ thĩ; na nĩgũgakinya atĩrĩ, atĩ mũndũ ũrĩa wothe ũkangorera no kũũraga akangaũraga.',
    15:'Nake Jehova akĩmũĩra atĩrĩ, Tondũ ũcio mũndũ ũrĩa ũkooraga Kaini akarĩhĩo maita mũgwanja. Nĩngĩ Jehova agĩtĩĩra Kaini rũrĩrĩ, nĩ getha mũndũ o na ũrĩkũ ũrĩa ũkamũkorerera ndakanamũũringe akue.',
    16:'Nake Kaini akiuma harĩ Jehova, agĩthĩĩ agĩtũũra bũrũri wa Nodu, ũrĩa warĩ rũere rũa kũu Edeni rũrĩa rĩũa rĩrathagĩra.',
    17:'Na rĩrĩ, Kaini akionana na mũka, nake akĩgia ihu, agĩciara Enoku; nĩngĩ agĩaka itũũra, akĩrĩtua Enoku o ta ũguo mũrũwe etagwo.',
    18:'Nake Enoku agĩciara Iradu, nake Iradu agĩciara Mehujaeli, nake Mehujaeli agĩciara Methushaeli, nake Methushaeli agĩciara Lameku.',
    19:'Nake Lameku ũcio akĩhikia aka erĩ; ũmwe wao etagwo Ada, na ũrĩa ũngĩ etagwo Zila.',
    20:'Nake Ada agĩciara Jabali; ũcio nĩwe ithe wa andũ arĩa matũũraga hema-inĩ na makagĩa na indo cia thakame.',
    21:'Nake mũrũ wa nyina etagwo Jubali, na nĩwe ithe wa andũ othe arĩa ahũĩ kĩnanda kĩa mũgeto na arĩa ahuhĩ mũtũrĩrũ.',
    22:'Nake ũcio wetagwo Zila agĩciara Tubali-Kaini, ũrĩa warĩ mwĩgithia wa mũtũri o wothe wa indo cia rũthũku na cia igera; na mwarĩ wa nyina na Tubali-Kaini etagwo Naama.',
    23:'Nake Lameku akĩĩra aka acio ake ũũ: Atĩrĩrĩ, inyuĩ Ada na Zila, ta iguai mũgambo wakwa; Inyuĩ, aka a Lameku, ta thĩkĩrĩria ũhoro nguga: Nĩ gũkorũo nĩngooraga mũndũ nĩ ũndũ wa kũnguraria, Njũrage kĩmwana nĩ ũndũ wa kũnĩkĩra nduutu.',
    24:'Kũngĩkorũo Kaini akarĩhĩrio maita mũgwanja-rĩ, Lameku nake ndaĩrĩ hingo atangĩthĩria maita mĩrongo mũgwanja na mũgwanja.',
    25:'Nĩngĩ Adamu agĩcoka akionana na mũka rĩngĩ nake agĩciara kahĩĩ, agĩgatua Sethu, akiuga atĩrĩ, Nĩ ũndũ Ngai nĩatũmĩte ngĩe na mbeũ ĩngĩ ithenya rĩa Habili; tondũ we nĩoragĩrũo nĩ Kaini.',
    26:'O nake Sethu agĩciarĩrũo kahĩĩ, agĩgatua Enoshu; hĩndĩ ĩo nĩyo andũ maambĩrĩrie gũthathayagia Jehova makĩgwetaga rĩtwa rĩu rĩake.',
},

      5:{
    1:'Rĩrĩ nĩrĩo ibuku rĩa njaruo cia Adamu. Mũthenya ũrĩa Ngai aatũmire andũ magĩe-rĩ, aamombire matarĩ ta mũhianĩre wa Ngai;',
    2:'agĩtũma magĩe kuo marĩ mũndũ mũrũme na mũndũ mũka; na mũthenya ũcio aatũmire magĩe kuo-rĩ, akĩmarathima, na agĩtua rĩtwa rĩao Mũndũ.',
    3:'Nake Adamu aatũũra mĩaka igana rĩa mĩrongo ĩtatũ, agĩciara kahĩĩ kamũtũkĩtie, ke na mũhianĩre o ta wake mwene, agĩgatua Sethu;',
    4:'nĩngĩ matukũ marĩa Adamu aacokire gũtũũra muoyo aarĩkia gũciara Sethu, nĩ mĩaka magana manana; na nĩaciarire ihĩĩ ingĩ, o na airĩtu.',
    5:'Namo matukũ mothe ma Adamu aatũũrire muoyo nĩ mĩaka magana kenda ma mĩrongo ĩtatũ, agĩtũkua.',
    6:'Nake Sethu aakinya mĩaka igana na ĩtano, agĩciara Enoshu;',
    7:'na aarĩkia gũciara Enoshu, agĩtũũra muoyo mĩaka ĩngĩ magana manana na mũgwanja, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    8:'Namo matukũ mothe ma Sethu maarĩ mĩaka magana kenda ma ikũmi na ĩĩrĩ, agĩtũkua.',
    9:'Nake Enoshu aakinya mĩaka mĩrongo kenda, agĩciara Kenani;',
    10:'na aarĩkia gũciara Kenani, agĩtũũra muoyo mĩaka ĩngĩ magana manana ma ikũmi na ĩtano, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    11:'Namo matukũ mothe ma Enoshu maarĩ mĩaka magana kenda na ĩtano, agĩtũkua.',
    12:'Nake Kenani aakinya mĩaka mĩrongo mũgwanja, agĩciara Mahalaleli;',
    13:'na aarĩkia gũciara Mahalaleli, agĩtũũra muoyo mĩaka ĩngĩ magana manana na mĩrongo ĩna, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    14:'Namo matukũ mothe ma Kenani maarĩ mĩaka magana kenda na ikũmi, agĩtũkua.',
    15:'Nake Mahalaleli aakinya mĩaka mĩrongo ĩtandatũ na ĩtano, agĩciara Jaredu;',
    16:'na aarĩkia gũciara Jaredu, agĩtũũra muoyo mĩaka ĩngĩ magana manana ma mĩrongo ĩtatũ, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    17:'Namo matukũ mothe ma Mahalaleli maarĩ mĩaka magana manana ma mĩrongo kenda na ĩtano, agĩtũkua.',
    18:'Nake Jaredu aakinya mĩaka igana rĩa mĩrongo ĩtandatũ na ĩĩrĩ, agĩciara Enoku;',
    19:'na aarĩkia gũciara Enoku, agĩtũũra mĩaka ĩngĩ magana manana, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    20:'Namo matukũ mothe ma Jaredu maarĩ mĩaka magana kenda ma mĩrongo ĩtandatũ na ĩĩrĩ, agĩtũkua.',
    21:'Nake Enoku aakinya mĩaka mĩrongo ĩtandatũ na ĩtano, agĩciara Methusela;',
    22:'na aarĩkia gũciara Methusela, agĩtũũra e mũthĩrĩtu wa Ngai mĩaka ĩngĩ magana matatũ, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    23:'Namo matukũ mothe ma Enoku maarĩ mĩaka magana matatũ ma mĩrongo ĩtandatũ na ĩtano,',
    24:'nake Enoku ũcio nĩaatũũrire e mũthĩrĩtu wa Ngai, agĩtiya kwagwo, nĩ ũndũ Ngai nĩaathire nake.',
    25:'Nake Methusela aakinya mĩaka igana rĩa mĩrongo ĩna na ĩtano, agĩciara Lameku;',
    26:'na aarĩkia gũciara Lameku, agĩtũũra muoyo mĩaka ĩngĩ magana mũgwanja ma mĩrongo ĩnana na ĩĩrĩ, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    27:'Namo matukũ mothe ma Methusela maarĩ mĩaka magana kenda ma mĩrongo ĩtandatũ na kenda, agĩtũkua.',
    28:'Nake Lameku aakinya mĩaka igana rĩa mĩrongo ĩnana na ĩĩrĩ, agĩciara kahĩĩ,',
    29:'agĩgatua Nuhu, akiuga atĩrĩ, Ũyũ nĩwe wa gũtũthoria nĩ ũndũ wa mawĩra maitũ na mĩnoga ya moko maitũ, ĩrĩa yumanaga na tĩrĩ ĩyũ Jehova atũmĩte ĩtũũre wĩ mũthahu.',
    30:'Nake Lameku aarĩkia gũciara Nuhu, agĩtũũra mĩaka ĩngĩ magana matano na mĩrongo kenda na ĩtano, na nĩaciarire ihĩĩ ingĩ o na airĩtu.',
    31:'Namo matukũ mothe ma Lameku maarĩ mĩaka magana mũgwanja ma mĩrongo mũgwanja na mũgwanja, agĩtũkua.',
    32:'Nake Nuhu aakinya mĩaka magana matano, agĩciara Shemu, na Hamu, na Jafethu.',
},

